  function liveCss(){if(document.getElementById("kofferLiveCss"))return;const s=document.createElement("style");s.id="kofferLiveCss";s.textContent=`.koffer-live{position:fixed;z-index:9999;right:24px;top:100px;width:min(720px,calc(100vw - 32px));max-height:82vh;resize:both;overflow:auto;border:1px solid #89958b;border-radius:14px;background:#e7e7e4;box-shadow:0 18px 60px #0005}.koffer-live[hidden]{display:none}.koffer-live-head{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:#15241a;color:#fff;cursor:move}.koffer-live-head button{border:0;border-radius:7px;padding:5px 9px;cursor:pointer}.koffer-paper{margin:18px auto;padding:32px;width:92%;min-height:600px;background:#fff;color:#222;box-shadow:0 2px 12px #0002}.koffer-paper-brand{font-weight:900;color:#367744;letter-spacing:2px}.koffer-paper-meta{display:flex;flex-direction:column;margin:18px 0}.koffer-paper table{width:100%;border-collapse:collapse;font-size:12px}.koffer-paper th,.koffer-paper td{padding:8px 5px;border-bottom:1px solid #ddd;text-align:right;vertical-align:top}.koffer-paper th:nth-child(2),.koffer-paper td:nth-child(2){text-align:left}.koffer-paper tfoot{font-weight:900}`;document.head.appendChild(s)}
  function bathAreas(){const c=draft.bathroomCalc||{},l=+c.length||0,w=+c.width||0,h=+c.height||0,wall=Math.max(0,2*(l+w)*h-(+c.wallDeduction||0)),floor=Math.max(0,l*w-(+c.floorDeduction||0)),ceiling=Math.max(0,l*w-(+c.ceilingDeduction||0)),lime=Math.min(wall,(+c.limeWallLength||0)*h)+ceiling,shower=Math.max(0,(+c.showerWallLength||0)*(+c.showerWallHeight||0)+floor);return{wall,floor,ceiling,lime,shower,fugenlos:Math.max(0,wall-Math.min(wall,(+c.limeWallLength||0)*h)+floor)}}
