    box.querySelectorAll("[data-type]").forEach(b=>b.onclick=()=>{draft.offerType=b.dataset.type;draft.positions=positions();box.remove();render()});box.querySelectorAll("[data-list]").forEach(x=>x.onchange=()=>{const key=x.dataset.list;draft[key]=[...box.querySelectorAll(`[data-list="${key}"]:checked`)].map(y=>y.value);syncPositions()});box.querySelectorAll("[data-bath-calc]").forEach(x=>x.oninput=()=>{draft.bathroomCalc[x.dataset.bathCalc]=Math.max(0,Number(x.value||0));syncPositions(true)});box.querySelectorAll("[data-measure]").forEach(x=>x.oninput=x.onchange=()=>{const key=x.dataset.measure;draft.measurement[key]=key==="mode"?x.value:Math.max(0,Number(x.value||0));if(key==="mode"){box.remove();render()}else syncPositions(true)});box.querySelectorAll("[data-standard]").forEach(x=>x.oninput=()=>{const key=x.dataset.standard,value=key==="materialMarkupPct"?Math.max(-100,Number(x.value||0)):Math.max(0,Number(x.value||0));draft.measurement[key]=value;for(const p of draft.positions){if(key==="hourlyRate"&&!p.hourlyRateOverridden)p.hourlyRate=value;if(key==="materialMarkupPct"&&!p.materialMarkupOverridden)p.materialMarkupPct=value;p.unitPrice=+calculatedPrice(costing(p)).toFixed(2)}renderPositions()});document.getElementById("kofferShowQty").onchange=e=>draft.showQuantities=e.target.checked;document.getElementById("kofferSave").onclick=save;renderPositions();renderAreaResult();renderMeasureResult();
