  async function printOffer(){const popup=window.open("","_blank");if(!popup){alert("Bitte Pop-ups für KRISTINE erlauben, damit die Druckansicht geöffnet werden kann.");return}popup.document.write('<p style="font-family:Arial;padding:30px">Angebot wird vorbereitet …</p>');try{await ensureOfferMaterials();await save();const finalized=await api(`/admin/api/job/${encodeURIComponent(jobId)}/offer-draft/finalize`,{method:"POST"});draft=finalized.draft;renderLivePreview();enhanceFinancialPreview();enhanceLivePreview();const paper=document.querySelector("#kofferLiveBody .koffer-paper");popup.document.open();popup.document.write(printDocumentHtml(paper));popup.document.close();document.getElementById("kofferMsg").textContent=`✓ Angebot ${draft.offerNumber} · intern V${draft.offerRevision} · Druckansicht geöffnet`;setTimeout(()=>{popup.focus();popup.print()},350)}catch(e){popup.close();document.getElementById("kofferMsg").textContent="Druckfehler: "+e.message}}
